module PitFilling1D {




 function Fill(a: seq<real>): seq<real>
 ensures |Fill(a)| == |a|
 {
 if |a| == 0 then []
 else
 var x := a[0];
 [x] + FillHelper(a[1..], x)
 }

 function FillHelper(a: seq<real>, last: real): seq<real>
 decreases |a|
 ensures |FillHelper(a, last)| == |a|
 {
 if |a| == 0 then []
 else
 var x := max(a[0], last);
 [x] + FillHelper(a[1..], x)
 }
